<?php require '../inc.php';guard('professor');$c=api('course','mine');$cc=array_column($c,'course_code','course_id');
if($_POST){isset($_POST['title'])?api('announcement','pcreate',[],$_POST):api('announcement','pdelete',[],['id'=>$_POST['id']]);header('Location: announcements.php');exit;}
$a=api('announcement','mine');top('Announcements','announcements');?>
<h1>Announcements <a class="btn" style="float:right;font-size:15px;text-decoration:none" href="?new=1"><?=ui_icon('megaphone')?> Post Announcement</a></h1><p class="sub">Post course-specific announcements</p>
<?php if(isset($_GET['new'])):?><form method="post" class="card"><div class="row"><select name="course_id" style="padding:14px"><?php foreach($c as $x):?><option value="<?=$x['course_id']?>"><?=h($x['course_code'])?></option><?php endforeach;?></select><input name="title" placeholder="Title" required></div><div class="row"><input name="content" placeholder="Message" required></div><button class="btn">Post</button></form><?php endif;?>
<?php foreach($a as $x):?><div class="card"><span class="tag" style="background:#e8f3ec;color:var(--g)"><?=h($cc[$x['course_id']]??'')?></span><form method="post" style="float:right" onsubmit="return confirm('Delete?')"><input type="hidden" name="id" value="<?=$x['announcement_id']?>"><button class="lnk d">Delete</button></form><h3><?=h($x['title'])?></h3><p><?=h($x['content'])?></p><p><small>Posted <?=h(substr($x['created_at'],0,10))?></small></p></div><?php endforeach;bottom();
